<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import crew from '../crew.json'
type Character={name:string;owner:string;class:string;level:number;color?:string;status?:string}
type Dashboard={activePlayers:number;totalLevels:number;deaths:number;playedHours:number;characters:Character[];events:{title:string;detail:string;type?:string}[]}
const route=ref(location.hash.slice(1)||"overview"), menu=ref(false), connected=ref(false), loading=ref(true), now=ref(Date.now()), showForm=ref(false), submitted=ref(false)
const crewMembers=ref<Array<{name:string;character:string;class:string;faction:string;roles?:string}>>(crew)
const sheetCsv='https://docs.google.com/spreadsheets/d/1SZIHizrbutMwKg25SF9vGVLSEMo_NIogMF4ZiJ20NcY/export?format=csv&gid=186545892'
const classIcons:Record<string,string>={Druid:'class_druid',Hunter:'class_hunter',Mage:'class_mage',Paladin:'class_paladin',Priest:'class_priest',Rogue:'class_rogue',Shaman:'class_shaman',Warlock:'class_warlock',Warrior:'class_warrior'}
function classIcon(className:string){const key=className.trim();return classIcons[key]?`https://wow.zamimg.com/images/wow/icons/medium/${classIcons[key]}.jpg`:''}
function factionIcon(faction:string){return faction==='Horde'?'https://wow.zamimg.com/images/wow/icons/tiny/side_horde.gif':faction==='Alliance'?'https://wow.zamimg.com/images/wow/icons/tiny/side_alliance.gif':''}
function parseCsv(csv:string){const rows=csv.trim().split(/\r?\n/).map(row=>row.split(/,(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)/).map(cell=>cell.replace(/^\"|\"$/g,'').replace(/\"\"/g,'\"')));const headers=rows.shift()?.map(h=>h.trim())||[];return rows.filter(row=>row.some(Boolean)).map(row=>{const item=Object.fromEntries(headers.map((header,index)=>[header,row[index]||'']));return {name:item['Your name / nickname']||'',character:'',class:item['Which class do you want to play?']||'',faction:item['Faction']||'',roles:item['Which roles are you interested in?']||''}}).filter(item=>item.name)}
const factions={Horde:['Orc','Undead','Tauren','Troll','Skyborne'],Alliance:['Human','Dwarf','Night Elf','Gnome','Skyborne']}
const combinations:Record<string,string[]>={Druid:['Night Elf','Tauren','Skyborne'],Hunter:['Human','Dwarf','Night Elf','Orc','Tauren','Troll','Skyborne'],Mage:['Human','Gnome','Undead','Troll','Skyborne'],Paladin:['Human','Dwarf','Undead'],Priest:['Human','Dwarf','Night Elf','Gnome','Undead','Troll'],Rogue:['Human','Dwarf','Night Elf','Gnome','Orc','Undead','Troll','Skyborne'],Shaman:['Dwarf','Orc','Tauren','Troll','Skyborne'],Warlock:['Human','Gnome','Orc','Undead','Troll'],Warrior:['Human','Dwarf','Night Elf','Gnome','Orc','Undead','Tauren','Troll','Skyborne']}
const form=reactive({name:'',faction:'',race:'',character:'',class:'',characters:[] as {character:string;race:string;class:string}[],launch:'yes',note:''})
const signupUrl='https://docs.google.com/forms/d/e/1FAIpQLSfbhURjHavL3GG5T9xTN_cvn3ZEy5uBthUCJQM5YTNDLmPbdg/viewform'
function openSignup(){showForm.value=true}
async function refreshCrew(){try{const response=await fetch(`${sheetCsv}&t=${Date.now()}`);if(response.ok){const members=parseCsv(await response.text());crewMembers.value=members as typeof crewMembers.value}}catch{/* keep current roster on refresh failure */}}
async function closeSignup(){showForm.value=false;await refreshCrew()}
const factionRaces=computed(()=>factions[form.faction as 'Horde'|'Alliance'] || [])
const availableClasses=computed(()=>Object.keys(combinations).filter(name=>form.race && combinations[name].includes(form.race)))
const allClasses=Object.keys(classIcons)
const allRoles=['DPS','Heal','Tank']
const foreverFacts=[
  {name:'Alchemy',icon:'trade_alchemy',bonus:'Longer duration and stronger effects from elixirs and flasks.',detail:'A strong all-round choice for players who want consistent consumable value in PvP and everyday play.'},
  {name:'Enchanting',icon:'inv_misc_scroll_02',bonus:'Enchant your own rings with Spell Power, Attack Power or Stamina.',detail:'Turns your rings into another source of permanent character power.'},
  {name:'Engineering',icon:'inv_misc_gear_01',bonus:'No additional stat bonus from the profession passive.',detail:'Engineering is about utility, gadgets and clever tools rather than a direct stat increase.'},
  {name:'Leatherworking',icon:'inv_misc_armorkit_17',bonus:'Temporary bracer armor kits with Spell Power, Attack Power or Stamina.',detail:'Useful preparation for players who want an extra temporary edge before a fight.'},
  {name:'Tailoring',icon:'inv_fabric_silk_02',bonus:'Cloak embroideries that grant Spell Power, Attack Power or Stamina.',detail:'A useful option for cloth wearers and anyone planning around spell or attack power.'},
  {name:'Herbalism',icon:'trade_herbalism',bonus:'Resistance to all schools of magic as skill increases.',detail:'Particularly interesting for PvP players who expect to fight a lot of casters.'},
  {name:'Skinning',icon:'inv_misc_pelt_wolf_01',bonus:'5% increased total health.',detail:'Simple and effective survivability for every character, regardless of class.'},
  {name:'Mining',icon:'inv_pick_02',bonus:'5% increased damage to Beasts and Dragonkin.',detail:'A situational damage bonus that becomes valuable in the right encounters.'}
]
const fieldNotes=[
  {route:'facts',category:'FOREVER UPDATE',title:'WORLD OF WARCRAFT: FOREVER OVERVIEW',text:'New zones, races, dungeons, professions, PvP and everything worth knowing before launch.',icon:'inv_misc_map_01'},
  {route:'professions',category:'PROFESSION NOTES',title:'PROFESSIONS',text:'Which professions add stats, utility and useful bonuses in Forever?',icon:'trade_alchemy'},
  {route:'article',category:'WORLD SYSTEMS',title:'CAMPING IN THE OPEN WORLD',text:'Build a campsite almost anywhere and let the crew turn tradeskills into shared buffs.',icon:'inv_misc_campfire',body:'Forever introduces campsites that can be created almost anywhere in the open world. Other players can use their tradeskills at the camp to grant group-wide profession buffs. It is a small system designed to make the world feel more social.'},
  {route:'article',category:'LEGACY SYSTEM',title:'LEVEL 60 IS NOT THE END',text:'Legacy Points turn exploration, PvP, professions and dungeons into account-wide progress.',icon:'achievement_general',body:'The Legacy system rewards challenges across the whole game: exploring, leveling classes, increasing tradeskills, earning PvP ranks, maximizing reputations and completing dungeons and raids. Points unlock non-combat perks and collection rewards for your account.'},
  {route:'article',category:'PVP NOTES',title:'DARKSPEAR ISLANDS',text:'A new 15v15 battleground built around interactive capture points.',icon:'achievement_bg_winwsg',body:'Darkspear Islands is a new 15v15 battleground with interactive objectives. Forever will also receive an updated seasonal PvP system, making this one of the most interesting features for the CzechDream crew.'},
  {route:'article',category:'ECONOMY',title:'NO GDKP',text:'Blizzard is taking a strict approach to the Forever economy.',icon:'inv_misc_coin_01',body:'GDKP will not be allowed in Forever. Blizzard has said that the game economy is being taken seriously, keeping the focus on playing together rather than turning raid loot into an auction.'}
]
const activeArticle=ref<typeof fieldNotes[number]|null>(null)
const selectedClasses=computed(()=>new Set(crewMembers.value.flatMap(member=>member.class.split(',').map(item=>item.trim()))))
const selectedRoles=computed(()=>new Set(crewMembers.value.flatMap(member=>(member.roles||'').split(',').map(item=>item.trim()).filter(Boolean))))
const roleCounts=computed(()=>Object.fromEntries(allRoles.map(role=>[role,crewMembers.value.filter(member=>(member.roles||'').split(',').map(item=>item.trim()).includes(role)).length])))
function addCharacter(){if(form.character&&form.race&&form.class){form.characters.push({character:form.character,race:form.race,class:form.class});form.character='';form.race='';form.class=''}}
function removeCharacter(index:number){form.characters.splice(index,1)}
async function submitForm(){const body=new URLSearchParams({'form-name':'crew-signup',name:form.name,faction:form.faction,race:form.race,character:form.character,class:form.class,characters:JSON.stringify(form.characters),launch:form.launch,note:form.note});await fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});submitted.value=true}
const data=ref<Dashboard>({activePlayers:0,totalLevels:0,deaths:0,playedHours:0,characters:[],events:[]})
const pages=[['overview','OVERVIEW']]
const title=computed(()=>pages.find(p=>p[0]===route.value)?.[1]||'OVERVIEW')
function navigate(to:string){route.value=to;menu.value=false;location.hash=to}
async function scrollToFacts(){navigate('overview');await nextTick();document.querySelector('.forever-facts')?.scrollIntoView({behavior:'smooth',block:'start'})}
function openFieldNote(note:typeof fieldNotes[number]){activeArticle.value=note;navigate(note.route)}
onMounted(async()=>{addEventListener('hashchange',()=>route.value=location.hash.slice(1)||'overview');try{const sheet=await fetch(sheetCsv);if(sheet.ok){const members=parseCsv(await sheet.text());if(members.length)crewMembers.value=members as typeof crewMembers.value}}catch{ /* keep empty roster when unavailable */ }try{const r=await fetch('/api/dashboard');const type=r.headers.get('content-type')||'';if(r.ok&&type.includes('application/json'))data.value=await r.json()}catch{ /* local Vite has no Netlify function; keep zero state */ }finally{loading.value=false}})
const launchAt=new Date("2026-11-05T00:00:00+01:00").getTime()
const countdown=computed(()=>{const s=Math.max(0,Math.floor((launchAt-now.value)/1000));return {days:Math.floor(s/86400),hours:Math.floor(s%86400/3600),minutes:Math.floor(s%3600/60),seconds:s%60}})
setInterval(()=>now.value=Date.now(),1000)
</script>
<template><div class="app-shell"><header class="topbar"><button class="mobile-menu" @click="menu=!menu">☰</button><div class="brand" @click="navigate('overview')"><div class="brand-mark">✦</div><div><b>CZECHDREAM</b><span>FOREVER</span></div></div><nav :class="{open:menu}"><a v-for="page in pages" :key="page[0]" :class="{selected:route===page[0]}" @click="navigate(page[0])">{{page[1]}}</a><a class="facts-nav-link" @click="scrollToFacts">FACTS</a><a href="https://talentsforever.com/" target="_blank" rel="noreferrer">TALENTS</a><a href="https://www.wowhead.com/forever/news" target="_blank" rel="noreferrer">NEWS</a><a href="https://discord.gg/cmtnpW7jUU" target="_blank" rel="noreferrer">DISCORD</a></nav><div class="resource-links"><a href="https://talentsforever.com/" target="_blank" rel="noreferrer">TALENTS</a><a href="https://www.wowhead.com/forever/news" target="_blank" rel="noreferrer">NEWS</a><a href="https://discord.gg/cmtnpW7jUU" target="_blank" rel="noreferrer">DISCORD</a></div><div class="top-actions"><span class="public-badge">PUBLIC GUILD DASHBOARD</span></div></header><main><section v-if="route==='overview'" class="launch-banner"><div><div class="kicker"><i></i> WORLD OF WARCRAFT: FOREVER</div><h2>THE JOURNEY BEGINS</h2><p>Global launch · 5 November 2026 · 00:00 CET</p></div><div class="countdown"><div><strong>{{String(countdown.days).padStart(2,'0')}}</strong><small>DAYS</small></div><b>:</b><div><strong>{{String(countdown.hours).padStart(2,'0')}}</strong><small>HOURS</small></div><b>:</b><div><strong>{{String(countdown.minutes).padStart(2,'0')}}</strong><small>MIN</small></div><b>:</b><div><strong>{{String(countdown.seconds).padStart(2,'0')}}</strong><small>SEC</small></div></div></section><section v-if="route==='overview'" class="crew-signup-area"><div class="kicker"><i></i> CZECHDREAM CREW</div><h2>ZBYTOČNÍ ARE BACK!</h2><p>Tell us what you are playing and what you want to focus on in Forever.</p><div class="crew-list"><div v-if="!crewMembers.length" class="empty-state">Zatiaľ sa nepridal nikto. Buď prvý.</div><div v-for="member in crewMembers" :key="member.name" class="crew-member"><span class="faction-badge"><img v-if="factionIcon(member.faction)" :src="factionIcon(member.faction)" :alt="member.faction" :title="member.faction"></span><div class="member-identity"><strong>{{member.name}}</strong><small>{{member.roles || "No focus selected"}}</small></div><div class="member-classes"><span v-for="className in member.class.split(',')" :key="className" class="class-icon-wrap"><img v-if="classIcon(className)" :src="classIcon(className)" :alt="className.trim()" :title="className.trim()"><span class="class-tooltip">{{className.trim()}}</span></span></div></div></div><section class="coverage-board"><div class="coverage-heading"><div><div class="kicker">CREW COMPOSITION</div><h3>WHAT WE HAVE · WHAT WE NEED</h3></div><span>{{crewMembers.length}} players locked in</span></div><div class="coverage-classes"><div v-for="className in allClasses" :key="className" :class="['coverage-class',{missing:!selectedClasses.has(className)}]"><span class="coverage-icon-wrap"><img :src="classIcon(className)" :alt="className"><span class="class-tooltip">{{className}}</span></span><small>{{className}}</small></div></div><div class="coverage-roles"><div v-for="role in allRoles" :key="role" :class="['coverage-role',{missing:!selectedRoles.has(role)}]"><strong>{{roleCounts[role]}}</strong><span>{{role}}</span><small>{{roleCounts[role] === 1 ? 'player' : 'players'}}</small></div></div></section><button class="gold-button join-button" @click="openSignup">JOIN THE CREW</button><div v-if="showForm" class="form-modal"><button type="button" class="form-close" @click="closeSignup">×</button><iframe :src="signupUrl" title="CzechDream Forever signup form"></iframe></div><form v-if="false" class="signup-form" name="crew-signup" .prevent="submitForm"><div v-if="submitted" class="success">Hotovo. Si zapísaný v CzechDream crew.</div><template v-else><input v-model="form.name" name="name" required placeholder="Tvoje meno / nick"><div class="faction-picker"><button type="button" :class="{chosen:form.faction==='Horde'}" @click="form.faction='Horde';form.race='';form.class=''"><img src="https://wow.zamimg.com/images/wow/icons/tiny/side_horde.gif" alt=""> HORDE</button><button type="button" :class="{chosen:form.faction==='Alliance'}" @click="form.faction='Alliance';form.race='';form.class=''"><img src="https://wow.zamimg.com/images/wow/icons/tiny/side_alliance.gif" alt=""> ALLIANCE</button></div><div class="choice-block"><label>RASA</label><div class="choice-grid"><button v-for="race in factionRaces" :key="race" type="button" :class="{chosen:form.race===race}" @click="form.race=race;form.class=''">{{race}}</button></div></div><div class="choice-block"><label>CLASSA</label><div class="choice-grid"><button v-for="className in availableClasses" :key="className" type="button" :class="{chosen:form.class===className}" @click="form.class=className">{{className}}</button></div></div><input v-model="form.character" name="character" required placeholder="Meno postavy"><button class="ghost-button add-character" type="button" @click="addCharacter">+ PRIDAŤ ĎALŠIU POSTAVU</button><div v-if="form.characters.length" class="planned-characters"><div v-for="(character,index) in form.characters" :key="index"><strong>{{character.character}}</strong><span>{{character.race}} · {{character.class}}</span><button type="button" @click="removeCharacter(index)">×</button></div></div><textarea v-model="form.note" name="note" placeholder="Poznámka"></textarea><button class="gold-button" type="submit">ZAPÍSAŤ MA →</button></template></form></section><section v-if="route==='overview'" class="forever-facts"><div class="kicker"><i></i> FOREVER FIELD NOTES</div><h2>SHORT READS FROM AZEROTH</h2><p class="facts-intro">Useful notes for the journey. More topics will be added as Forever gets closer.</p><div class="facts-grid"><article v-for="note in fieldNotes" :key="note.route" class="fact-card" @click="openFieldNote(note)"><div class="fact-cover"><img :src="`https://wow.zamimg.com/images/wow/icons/medium/${note.icon}.jpg`" :alt="note.title"></div><div class="fact-content"><small>{{note.category}}</small><strong>{{note.title}}</strong><span>{{note.text}}</span><b>READ NOTES ↗</b></div></article></div></section><section v-if="route==='facts'" class="facts-page"><button class="ghost-button facts-back" @click="navigate('overview')">← BACK TO OVERVIEW</button><div class="article-kicker"><span>FOREVER UPDATE</span><small>UPDATED 21 SEP 2026</small></div><h2>WORLD OF WARCRAFT: FOREVER OVERVIEW</h2><p class="article-lead">A new evolution of WoW Classic. Start fresh at level 1, explore a bigger Azeroth and build your legacy all the way to level 60.</p><div class="article-meta"><span>LAUNCH</span><strong>5 NOVEMBER 2026 · 00:00 CET</strong></div><div class="article-sections"><article><img src="https://wow.zamimg.com/images/wow/icons/medium/inv_misc_map_01.jpg" alt="New zones"><div><small>THE WORLD</small><h3>New zones and Skyborne</h3><p>Forever adds Mount Hyjal, Shen'Dralas, Riverglades and Zephras Isle. Skyborne can be played by both factions, with Shaman available to Horde and Mage to Alliance.</p></div></article><article><img src="https://wow.zamimg.com/images/wow/icons/medium/inv_sword_07.jpg" alt="Dungeons and raids"><div><small>ENDGAME</small><h3>New dungeons and raids</h3><p>Nine dungeons arrive at launch. The Barrow Deeps and Hyjal Summit open on 9 December, alongside the return of Onyxia's Lair.</p></div></article><article><img src="https://wow.zamimg.com/images/wow/icons/medium/trade_alchemy.jpg" alt="Professions"><div><small>PROFESSIONS</small><h3>Professions get meaningful bonuses</h3><p>Professions add passive stats, utility and preparation tools. Campsites also let players share profession-based buffs in the open world.</p></div></article><article><img src="https://wow.zamimg.com/images/wow/icons/medium/ability_hunter_mendpet.jpg" alt="Legacy system"><div><small>PROGRESSION</small><h3>Legacy system and talents</h3><p>Earn Legacy Points from exploring, leveling, tradeskills, PvP, reputations, dungeons and raids. Spend them on account-wide non-combat perks.</p></div></article><article><img src="https://wow.zamimg.com/images/wow/icons/medium/ability_warrior_bloodfrenzy.jpg" alt="PvP"><div><small>PVP</small><h3>Darkspear Islands</h3><p>A new 15v15 battleground joins an updated seasonal PvP system. Perfect for the CzechDream crew — we are going in mainly for PvP.</p></div></article><article><img src="https://wow.zamimg.com/images/wow/icons/medium/inv_chest_cloth_17.jpg" alt="Transmog"><div><small>YOUR CHARACTER</small><h3>Class changes and optional transmog</h3><p>New spells, talents, racials and class-race combinations arrive alongside an optional transmog system that can be disabled.</p></div></article></div></section><section v-if="route==='professions'" class="facts-page"><button class="ghost-button facts-back" @click="navigate('overview')">← BACK TO FIELD NOTES</button><div class="article-kicker"><span>PROFESSION NOTES</span><small>UPDATED 21 SEP 2026</small></div><h2>PROFESSIONS IN FOREVER</h2><p class="article-lead">A quick guide to the passive bonuses, stats and utility each profession brings to your character.</p><div class="profession-list"><article v-for="fact in foreverFacts" :key="fact.name" class="profession-card"><img :src="`https://wow.zamimg.com/images/wow/icons/medium/${fact.icon}.jpg`" :alt="fact.name"><div><small>PROFESSION</small><h3>{{fact.name}}</h3><strong>{{fact.bonus}}</strong><p>{{fact.detail}}</p></div></article></div></section><section v-if="route==='article' && activeArticle" class="facts-page"><button class="ghost-button facts-back" @click="navigate('overview')">← BACK TO FIELD NOTES</button><div class="article-kicker"><span>{{activeArticle.category}}</span><small>UPDATED 21 SEP 2026</small></div><h2>{{activeArticle.title}}</h2><p class="article-lead">{{activeArticle.text}}</p><div class="article-feature"><img :src="`https://wow.zamimg.com/images/wow/icons/medium/${activeArticle.icon}.jpg`" :alt="activeArticle.title"><p>{{activeArticle.body}}</p></div></section><section v-if="route==='overview'" class="resources"><div class="kicker"><i></i> FOREVER RESOURCES</div><h2>USEFUL LINKS FOR THE JOURNEY</h2><div class="resource-grid"><a class="resource-card" href="https://talentsforever.com/" target="_blank" rel="noreferrer"><span class="resource-icon">✦</span><span><strong>Talents Forever</strong><small>Plan your character build and talents.</small></span><b>↗</b></a><a class="resource-card" href="https://www.wowhead.com/forever/news" target="_blank" rel="noreferrer"><span class="resource-icon">✧</span><span><strong>Wowhead Forever News</strong><small>Latest news, updates and guides.</small></span><b>↗</b></a></div></section><section v-if="route==='overview'" class="hero"><div class="hero-copy"><div class="kicker"><i></i> THE CZECHDREAM GUILD</div><h1>ZBYTOČNÍ<br><em>SÚ SPÄŤ.</em></h1><p>A shared chronicle of every level, death, victory and ridiculous moment in Azeroth.</p><div class="hero-buttons"><button class="gold-button" @click="connected=!connected">{{connected?'BRIDGE CONNECTED':'CONNECT YOUR BRIDGE'}} <span>→</span></button><button class="ghost-button" @click="navigate('chronicle')">VIEW CHRONICLE</button></div></div><div class="hero-art"><div class="moon"></div><div class="mountain">⚔</div><div class="hero-tag"><strong>SEASON ONE</strong><span>THE JOURNEY BEGINS</span></div></div></section><section class="section-head"><div><div class="kicker">GUILD INTELLIGENCE</div><h2>{{title}}</h2></div><div class="live"><i></i>{{connected?'BRIDGE ONLINE':'AWAITING SYNC'}}</div></section><section v-if="route==='overview'" class="stats"><article><span class="stat-icon">♙</span><div><small>ACTIVE PLAYERS</small><strong>{{data.activePlayers}}</strong><label>from synced data</label></div></article><article><span class="stat-icon gold">♜</span><div><small>TOTAL LEVELS</small><strong>{{data.totalLevels}}</strong><label>across all characters</label></div></article><article><span class="stat-icon red">☠</span><div><small>DEATHS RECORDED</small><strong>{{data.deaths}}</strong><label>from synced events</label></div></article><article><span class="stat-icon purple">◈</span><div><small>TIME TOGETHER</small><strong>{{data.playedHours}}h</strong><label>from synced sessions</label></div></article></section><section v-if="route==='overview'||route==='crew'||route==='characters'" class="content-grid"><article class="panel wide"><div class="panel-title"><div><div class="kicker">THE PARTY</div><h3>{{route==='crew'?'CREW MEMBERS':'CHARACTER ROSTER'}}</h3></div></div><div class="roster-row header-row"><span>CHARACTER</span><span>CLASS</span><span>LEVEL</span><span>STATUS</span></div><div v-if="loading" class="empty-state">Loading guild data...</div><div v-else-if="!data.characters.length" class="empty-state">No characters synced yet. Connect a CzechDream Bridge.</div><div v-for="player in data.characters" v-else :key="player.name" class="roster-row"><div class="character"><span :class="['portrait',player.color]">{{player.name[0]}}</span><div><b>{{player.name}}</b><small>{{player.owner}}</small></div></div><span class="class-name">{{player.class}}</span><b class="level">{{player.level}}</b><span :class="['player-status',player.status]"><i></i>{{player.status}}</span></div></article><article v-if="route==='overview'" class="panel"><div class="panel-title"><div><div class="kicker">RECENT MOMENTS</div><h3>THE CHRONICLE</h3></div></div><div v-if="!data.events.length" class="empty-state">No events synced yet.</div><div v-else class="timeline"><div v-for="event in data.events.slice(0,5)" :key="event.title"><span class="event-icon death">✦</span><p><b>{{event.title}}</b><small>{{event.detail}}</small></p></div></div></article></section><section v-if="route==='chronicle'" class="panel chronicle-page"><div class="panel-title"><div><div class="kicker">ALL GUILD EVENTS</div><h3>THE CHRONICLE</h3></div></div><div v-if="!data.events.length" class="empty-state">No events synced yet. Your guild story will appear here.</div><div v-else class="timeline"><div v-for="event in data.events" :key="event.title"><span class="event-icon death">✦</span><p><b>{{event.title}}</b><small>{{event.detail}}</small></p></div></div></section></main><footer><span>© 2026 CZECHDREAM FOREVER</span><span>PUBLIC GUILD CHRONICLE · AZEROTH</span></footer></div></template>
